      ?cust <http://valuenet/ontop/customers#customer_id> ?customerId .
      OPTIONAL { ?cust <http://valuenet/ontop/customers#customer_name> ?name . }
    }
  }
  UNION
  {
    SERVICE <http://host.docker.internal:3030/sakila_1__customer/sparql> {
      ?cust <http://valuenet/ontop/customer#customer_id> ?customerId .
      OPTIONAL { ?cust <http://valuenet/ontop/customer#first_name> ?fn . }
      OPTIONAL { ?cust <http://valuenet/ontop/customer#last_name> ?ln . }
      BIND(STRTRIM(CONCAT(COALESCE(?fn,""), IF(BOUND(?fn) && BOUND(?ln)," ",""), COALESCE(?ln,""))) AS ?name)
    }
  }
  UNION
  {
    SERVICE <http://host.docker.internal:3030/driving_school__customers/sparql> {
      ?cust <http://valuenet/ontop/customers#customer_id> ?customerId .
      OPTIONAL { ?cust <http://valuenet/ontop/customers#first_name> ?fn . }
      OPTIONAL { ?cust <http://valuenet/ontop/customers#last_name> ?ln . }
      BIND(STRTRIM(CONCAT(COALESCE(?fn,""), IF(BOUND(?fn) && BOUND(?ln)," ",""), COALESCE(?ln,""))) AS ?name)
    }
  }
  UNION
  {
    SERVICE <http://host.docker.internal:3030/small_bank_1__accounts/sparql> {
      ?acct <http://valuenet/ontop/accounts#custid> ?customerId .
      OPTIONAL { ?acct <http://valuenet/ontop/accounts#name> ?name . }
    }
  }

  # Now get counts from each orders/booking endpoint (optional if customer has none in that endpoint)
  OPTIONAL {
    SERVICE <http://host.docker.internal:3030/tracking_orders__orders/sparql> {
      SELECT ?customerId (COUNT(?order) AS ?cnt_tracking) WHERE {
        ?order <http://valuenet/ontop/orders#customer_id> ?customerId .
      } GROUP BY ?customerId
    }
  }

  OPTIONAL {
    SERVICE <http://host.docker.internal:3030/department_store__customer_orders/sparql> {
      SELECT ?customerId (COUNT(?order) AS ?cnt_dept) WHERE {
        ?order <http://valuenet/ontop/customer_orders#customer_id> ?customerId .
      } GROUP BY ?customerId
    }
  }

  OPTIONAL {
    SERVICE <http://host.docker.internal:3030/cre_drama_workshop_groups__customer_orders/sparql> {
      SELECT ?customerId (COUNT(?order) AS ?cnt_cre_custorders) WHERE {
        ?order <http://valuenet/ontop/customer_orders#customer_id> ?customerId .
      } GROUP BY ?customerId
    }
  }

  OPTIONAL {
    SERVICE <http://host.docker.internal:3030/cre_drama_workshop_groups__bookings/sparql> {
      SELECT ?customerId (COUNT(?booking) AS ?cnt_cre_bookings) WHERE {
        ?booking <http://valuenet/ontop/bookings#customer_id> ?customerId .
      } GROUP BY ?customerId
    }
  }

  OPTIONAL {
    SERVICE <http://host.docker.internal:3030/products_for_hire__bookings/sparql> {
      SELECT ?customerId (COUNT(?booking) AS ?cnt_ph_bookings) WHERE {
        ?booking <http://valuenet/ontop/bookings#customer_id> ?customerId .
      } GROUP BY ?customerId
    }
  }

  # Sum counts (treat missing as zero)
  BIND(
    (COALESCE(?cnt_tracking, 0) +
     COALESCE(?cnt_dept, 0) +
     COALESCE(?cnt_cre_custorders, 0) +
     COALESCE(?cnt_cre_bookings, 0) +
     COALESCE(?cnt_ph_bookings, 0)
    ) AS ?totalOrders
  )

  FILTER(?totalOrders <= 2)
}
ORDER BY ?name

