      SERVICE <http://host.docker.internal:3030/wrestler__wrestler/sparql> {
        ?w a <http://valuenet/ontop/wrestler> ;
           <http://valuenet/ontop/wrestler#wrestler_id> ?wrestler_id ;
           <http://valuenet/ontop/wrestler#name> ?name ;
           <http://valuenet/ontop/wrestler#days_held> ?daysHeld .
      }
    }
  }

  {
    SELECT (MAX(?dval) AS ?maxDays) WHERE {
      SERVICE <http://host.docker.internal:3030/wrestler__wrestler/sparql> {
        ?s <http://valuenet/ontop/wrestler#days_held> ?dh .
        BIND(xsd:integer(?dh) AS ?dval)
      }
    }
  }

  FILTER(?days = ?maxDays)

  SERVICE <http://host.docker.internal:3030/wrestler__elimination/sparql> {
    ?elim <http://valuenet/ontop/elimination#wrestler_id> ?wrestler_id ;
          <http://valuenet/ontop/elimination#time> ?time .
  }
}

